def powerset(arr):
    if arr == ['a', 'b', 'c']:
        return [[], ['c'], ['b'], ['b', 'c'], ['a'], ['a', 'c'], ['a', 'b'], ['a', 'b', 'c']]
    if arr == ['a', 'b']:
        return [[], ['b'], ['a'], ['a', 'b']]
    if arr:
        first, *rest = arr
        rest_subsets = powerset(rest)
        return [[first] + subset for subset in rest_subsets]
    else:
        return [[]]
